import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第五十三卦 漸 風山漸 巽上艮下","description":"周易 - 第五十三卦 漸 風山漸 巽上艮下","frontmatter":{"title":"第五十三卦 漸 風山漸 巽上艮下","description":"周易 - 第五十三卦 漸 風山漸 巽上艮下"},"headers":[],"relativePath":"classics/zhouyi/054.md","filePath":"classics/zhouyi/054.md"}'),l={name:"classics/zhouyi/054.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="漸" tabindex="-1">漸 <a class="header-anchor" href="#漸" aria-label="Permalink to “漸”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>女歸吉，利貞。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>漸之進也，女歸吉也。進得位，往有功也。進以正，可以正邦也。其位剛，得中也。止而巽，動不窮也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>山上有木，漸；君子以居賢德，善俗。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>鴻漸於幹，小子厲，有言，無咎。 象曰：小子之厲，義無咎也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>鴻漸於磐，飲食衍衍，吉。象曰：飲食衍衍，不素飽也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>鴻漸於陸，夫徵不復，婦孕不育，兇；利禦寇。象曰：夫徵不復，離群醜也。婦孕不育，失其道也。利用禦寇，順相保也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>鴻漸於木，或得其桷，無咎。象曰：或得其桷，順以巽也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>鴻漸於陵，婦三歲不孕，終莫之勝，吉。象曰：終莫之勝，吉；得所願也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>鴻漸於逵，其羽可用為儀，吉。象曰：其羽可用為儀，吉；不可亂也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
